# Let's test candidate triggers by creating images with patches
# We'll use a few clean images and stamp potential triggers on them

# Get a sample clean image
sample_img = x_clean[0:1].clone()  # (1, 3, 32, 32)
orig_label = y_clean[0].item()
print(f"Original image label: {orig_label} ({CLASSES[orig_label]})")

# Test different trigger positions and patterns
def test_trigger(pattern_type, corner, size=4):
    """
    pattern_type: 'white', 'checkerboard', 'random'
    corner: 'tl', 'tr', 'bl', 'br' (top-left, top-right, bottom-left, bottom-right)
    """
    img = sample_img.clone()

    # Position: 1 pixel in from corner
    if corner == 'tl':
        h_start, w_start = 1, 1
    elif corner == 'tr':
        h_start, w_start = 1, 32 - 1 - size
    elif corner == 'bl':
        h_start, w_start = 32 - 1 - size, 1
    elif corner == 'br':
        h_start, w_start = 32 - 1 - size, 32 - 1 - size

    if pattern_type == 'white':
        patch = torch.ones(3, size, size, dtype=torch.uint8) * 255
    elif pattern_type == 'checkerboard':
        patch = torch.zeros(3, size, size, dtype=torch.uint8)
        for c in range(3):
            for i in range(size):
                for j in range(size):
                    if (i + j) % 2 == 0:
                        patch[c, i, j] = 255
    elif pattern_type == 'random':
        patch = torch.randint(0, 2, (3, size, size), dtype=torch.uint8) * 255

    img[:, :, h_start:h_start+size, w_start:w_start+size] = patch
    return img

# Test a few combinations
for corner in ['tl', 'tr', 'bl', 'br']:
    for pattern in ['white', 'checkerboard', 'random']:
        for size in [3, 4, 5]:
            img = test_trigger(pattern, corner, size)
            logits = forward(W, img)
            probs = torch.softmax(logits, dim=1)
            pred = logits.argmax(dim=1).item()
            conf = probs.max().item()
            if pred != orig_label:
                print(f"  {pattern} {corner} size={size}: pred={pred} ({CLASSES[pred]}), conf={conf:.4f}")

# Let's test on multiple clean images to see if any trigger works
# Try a batch of images

for corner in ['tl', 'tr', 'bl', 'br']:
    for pattern in ['white', 'checkerboard', 'random']:
        for size in [3, 4, 5]:
            # Test on first 20 images
            imgs = []
            labels = []
            for i in range(20):
                img = test_trigger(pattern, corner, size)
                imgs.append(img)
                labels.append(y_clean[i].item())

            batch = torch.cat(imgs, dim=0)
            logits = forward(W, batch)
            preds = logits.argmax(dim=1)

            # Count how many changed to each class
            for c in range(10):
                count = (preds == c).sum().item()
                if count > 0:
                    print(f"  {pattern} {corner} size={size}: class {c} ({CLASSES[c]}) got {count} predictions")
